:root {
  --bg-dark: #111111;
  --bg-darker: #0a0a0a;
  --bg-panel: #1a1a1a;
  --primary-red: #E63946;
  --primary-red-hover: #c02835;
  --text-light: #ffffff;
  --text-muted: #a0a0a0;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-light);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  margin-bottom: 1rem;
  line-height: 1.2;
}

h1 { font-size: 4rem; letter-spacing: 2px; }
h2 { font-size: 3rem; letter-spacing: 1.5px; }
h3 { font-size: 2rem; letter-spacing: 1px; }

p { margin-bottom: 1.5rem; }

a {
  color: var(--primary-red);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--primary-red-hover);
}

ul { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.text-red { color: var(--primary-red); }
.text-center { text-align: center; }

/* Buttons */
.btn {
  display: inline-block;
  padding: 16px 32px;
  background-color: var(--primary-red);
  color: var(--text-light) !important;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  border: 2px solid var(--primary-red);
  cursor: pointer;
  transition: var(--transition);
  text-align: center;
  letter-spacing: 1px;
}

.btn:hover {
  background-color: transparent;
  color: var(--primary-red) !important;
}

.btn-outline {
  background-color: transparent;
  color: var(--text-light) !important;
  border-color: var(--text-light);
}

.btn-outline:hover {
  background-color: var(--text-light);
  color: var(--bg-dark) !important;
}

/* Header */
header {
  background-color: rgba(17, 17, 17, 0.95);
  position: fixed;
  top: 0;
  width: 100%;
  z-index: 1000;
  border-bottom: 1px solid #333;
  padding: 15px 0;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--text-light);
  letter-spacing: 2px;
}

.nav-links {
  display: flex;
  gap: 20px;
}

.nav-links a {
  color: var(--text-light);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.9rem;
  letter-spacing: 1px;
}

.nav-links a:hover {
  color: var(--primary-red);
}

/* Hero Sections */
.hero {
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background-color: var(--bg-darker);
  background-size: cover;
  background-position: center;
  padding: 120px 20px 60px;
  position: relative;
}

.hero::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.hero-content p {
  font-size: 1.2rem;
  margin-bottom: 2rem;
}

.hero .btn-group {
  display: flex;
  gap: 20px;
  justify-content: center;
}

/* Sections */
section {
  padding: 100px 0;
}

.bg-panel {
  background-color: var(--bg-panel);
}

.section-header {
  text-align: center;
  margin-bottom: 60px;
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 30px;
}

/* Feature Cards */
.feature-card {
  background: var(--bg-darker);
  padding: 40px 30px;
  border-top: 4px solid var(--primary-red);
  text-align: center;
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-5px);
}

.feature-card h3 {
  margin-bottom: 15px;
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 30px;
}

.schedule-table th, .schedule-table td {
  padding: 20px;
  border-bottom: 1px solid #333;
  text-align: left;
}

.schedule-table th {
  font-family: var(--font-heading);
  text-transform: uppercase;
  color: var(--primary-red);
  font-size: 1.2rem;
}

/* Floor vs Treadmill Toggle */
.toggle-container {
  display: flex;
  justify-content: center;
  margin-bottom: 40px;
  background: #222;
  border-radius: 30px;
  padding: 5px;
  max-width: 400px;
  margin-left: auto;
  margin-right: auto;
}

.toggle-btn {
  flex: 1;
  padding: 12px 24px;
  border: none;
  background: transparent;
  color: var(--text-light);
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  cursor: pointer;
  border-radius: 25px;
  transition: var(--transition);
}

.toggle-btn.active {
  background: var(--primary-red);
}

.toggle-content {
  display: none;
  background: var(--bg-panel);
  padding: 40px;
  border-radius: 8px;
  text-align: center;
}

.toggle-content.active {
  display: block;
  animation: fadeIn 0.5s ease;
}

/* Instructor Grid */
.filter-controls {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 40px;
}

.filter-btn {
  background: #222;
  border: 1px solid #444;
  color: var(--text-light);
  padding: 8px 16px;
  cursor: pointer;
  font-family: var(--font-body);
  transition: var(--transition);
}

.filter-btn:hover, .filter-btn.active {
  background: var(--primary-red);
  border-color: var(--primary-red);
}

.instructor-card {
  background: var(--bg-panel);
  overflow: hidden;
  position: relative;
}

.instructor-card img {
  width: 100%;
  height: 350px;
  object-fit: cover;
  filter: grayscale(100%);
  transition: var(--transition);
}

.instructor-card:hover img {
  filter: grayscale(0%);
}

.instructor-info {
  padding: 20px;
  text-align: center;
}

.instructor-info h3 { margin-bottom: 5px; }
.instructor-info p { color: var(--text-muted); margin-bottom: 15px; }

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  background: #000;
  padding: 50px 0;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease-in-out;
}

.carousel-slide {
  min-width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0 20px;
}

.carousel-slide img {
  max-width: 100%;
  height: 500px;
  object-fit: cover;
  border: 4px solid var(--bg-panel);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(230, 57, 70, 0.8);
  color: #fff;
  border: none;
  width: 50px;
  height: 50px;
  font-size: 1.5rem;
  cursor: pointer;
  z-index: 10;
  transition: var(--transition);
}
.carousel-btn:hover { background: var(--primary-red); }
.carousel-btn.prev { left: 20px; }
.carousel-btn.next { right: 20px; }

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid #333;
  margin-bottom: 10px;
}

.faq-question {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: var(--text-light);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  padding: 20px 0;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-question::after {
  content: '+';
  color: var(--primary-red);
  font-size: 2rem;
}

.faq-question.active::after {
  content: '−';
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--text-muted);
}

.faq-answer p {
  padding-bottom: 20px;
}

/* Newsletter Form */
.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 0 auto;
  position: relative;
}

.newsletter-form input {
  flex: 1;
  padding: 15px 20px;
  background: #222;
  border: 1px solid #444;
  color: #fff;
  font-family: var(--font-body);
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--primary-red);
}

.newsletter-form button {
  padding: 15px 30px;
  background: var(--primary-red);
  color: #fff;
  border: none;
  font-family: var(--font-heading);
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
}

.form-msg {
  position: absolute;
  bottom: -30px;
  left: 0;
  width: 100%;
  text-align: center;
  font-size: 0.9rem;
}

/* Footer */
footer {
  background: var(--bg-darker);
  padding: 80px 0 40px;
  border-top: 1px solid #222;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h4 {
  color: var(--text-muted);
  font-size: 1rem;
  margin-bottom: 20px;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  color: #fff;
  font-size: 0.9rem;
}

.footer-col ul li a:hover {
  color: var(--primary-red);
}

.footer-bottom {
  border-top: 1px solid #333;
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.country-select {
  background: #222;
  color: #fff;
  border: 1px solid #444;
  padding: 8px 15px;
  font-family: var(--font-body);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@media (max-width: 768px) {
  h1 { font-size: 3rem; }
  h2 { font-size: 2.2rem; }
  .grid-2 { grid-template-columns: 1fr; }
  .nav-links { display: none; } /* Mobile nav could be implemented if required */
  .hero .btn-group { flex-direction: column; }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. Floor vs Treadmill Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  if (toggleBtns.length > 0) {
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        const targetId = e.target.getAttribute('data-target');

        // Remove active class from all buttons and contents
        document.querySelectorAll('.toggle-btn').forEach(b => b.classList.remove('active'));
        document.querySelectorAll('.toggle-content').forEach(c => c.classList.remove('active'));

        // Add active class to clicked button and target content
        e.target.classList.add('active');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // 2. Instructor Filtering
  const filterBtns = document.querySelectorAll('.filter-btn');
  const instructorCards = document.querySelectorAll('.instructor-card');

  if (filterBtns.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        // Active state
        filterBtns.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');

        const filterValue = e.target.getAttribute('data-filter');

        instructorCards.forEach(card => {
          if (filterValue === 'all' || card.getAttribute('data-location') === filterValue) {
            card.style.display = 'block';
          } else {
            card.style.display = 'none';
          }
        });
      });
    });
  }

  // 3. Carousel
  const track = document.querySelector('.carousel-track');
  const slides = document.querySelectorAll('.carousel-slide');
  const nextBtn = document.querySelector('.carousel-btn.next');
  const prevBtn = document.querySelector('.carousel-btn.prev');

  if (track && slides.length > 0) {
    let currentIndex = 0;

    const updateCarousel = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    nextBtn.addEventListener('click', () => {
      currentIndex = (currentIndex + 1) % slides.length;
      updateCarousel();
    });

    prevBtn.addEventListener('click', () => {
      currentIndex = (currentIndex - 1 + slides.length) % slides.length;
      updateCarousel();
    });

    // Optional: Swipe support
    let startX = 0;
    track.addEventListener('touchstart', e => { startX = e.touches[0].clientX; });
    track.addEventListener('touchend', e => {
      const endX = e.changedTouches[0].clientX;
      if (startX - endX > 50) { currentIndex = (currentIndex + 1) % slides.length; updateCarousel(); }
      else if (endX - startX > 50) { currentIndex = (currentIndex - 1 + slides.length) % slides.length; updateCarousel(); }
    });
  }

  // 4. FAQ Accordion
  const faqQuestions = document.querySelectorAll('.faq-question');

  if (faqQuestions.length > 0) {
    faqQuestions.forEach(question => {
      question.addEventListener('click', () => {
        const isActive = question.classList.contains('active');

        // Close all
        faqQuestions.forEach(q => {
          q.classList.remove('active');
          q.nextElementSibling.style.maxHeight = null;
        });

        // Open if wasn't active
        if (!isActive) {
          question.classList.add('active');
          const answer = question.nextElementSibling;
          answer.style.maxHeight = answer.scrollHeight + "px";
        }
      });
    });
  }

  // 5. Newsletter Validation
  const newsletterForm = document.getElementById('newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailInput = document.getElementById('email-input').value;
      const msgArea = document.getElementById('form-msg');

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (emailRegex.test(emailInput)) {
        msgArea.textContent = 'Thanks for subscribing! Check your inbox.';
        msgArea.style.color = '#4CAF50'; // Green
        newsletterForm.reset();
      } else {
        msgArea.textContent = 'Please enter a valid email address.';
        msgArea.style.color = 'var(--primary-red)';
      }
    });
  }
});

