  height: 500px;
  object-fit: cover;
  border: 4px solid var(--bg-panel);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(230, 57, 70, 0.8);
  color: #fff;
  border: none;
  width: 50px;
  height: 50px;
  font-size: 1.5rem;
  cursor: pointer;
  z-index: 10;
  transition: var(--transition);
}
.carousel-btn:hover { background: var(--primary-red); }
.carousel-btn.prev { left: 20px; }
.carousel-btn.next { right: 20px; }

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid #333;
  margin-bottom: 10px;
}

.faq-question {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: var(--text-light);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  padding: 20px 0;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-question::after {
  content: '+';
  color: var(--primary-red);
  font-size: 2rem;
}

.faq-question.active::after {
  content: '−';
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--text-muted);
}

.faq-answer p {
  padding-bottom: 20px;
}

/* Newsletter Form */
.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 0 auto;
  position: relative;
}

.newsletter-form input {
  flex: 1;
  padding: 15px 20px;
  background: #222;
  border: 1px solid #444;
  color: #fff;
  font-family: var(--font-body);
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--primary-red);
}

.newsletter-form button {
  padding: 15px 30px;
  background: var(--primary-red);
  color: #fff;
  border: none;
  font-family: var(--font-heading);
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
}

.form-msg {
  position: absolute;
  bottom: -30px;
  left: 0;
  width: 100%;
  text-align: center;
  font-size: 0.9rem;
}

/* Footer */
footer {
  background: var(--bg-darker);
  padding: 80px 0 40px;
  border-top: 1px solid #222;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h4 {
  color: var(--text-muted);
  font-size: 1rem;
  margin-bottom: 20px;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  color: #fff;
  font-size: 0.9rem;
}

.footer-col ul li a:hover {
  color: var(--primary-red);
}

.footer-bottom {
  border-top: 1px solid #333;
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.country-select {
  background: #222;
  color: #fff;
  border: 1px solid #444;
  padding: 8px 15px;
  font-family: var(--font-body);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@media (max-width: 768px) {
  h1 { font-size: 3rem; }
  h2 { font-size: 2.2rem; }
  .grid-2 { grid-template-columns: 1fr; }
  .nav-links { display: none; } /* Mobile nav could be implemented if required */
  .hero .btn-group { flex-direction: column; }
}

